import os
os.environ['OPENBLAS_NUM_THREADS']='1';os.environ['OMP_NUM_THREADS']='1'
import pickle,itertools,json,time
import numpy as np
from sklearn.linear_model import Ridge,HuberRegressor,QuantileRegressor
from sklearn.preprocessing import StandardScaler
from sklearn.pipeline import make_pipeline
from sklearn.svm import SVR
from sklearn.ensemble import ExtraTreesRegressor,HistGradientBoostingRegressor,GradientBoostingRegressor
rows,y,g=pickle.load(open('dataset.pkl','rb'));ug=np.unique(g);folds=[(np.where(g!=k)[0],np.where(g==k)[0]) for k in ug]
sets={
'simple':['t','t2','t3','watts_first','age'],
'phys':['t','t2','t3','watts_first','age','wkg','work','watts_drop'],
'hr':['t','t2','t3','watts_first','age','hr_first','hr_change','hr_ema15'],
'skin':['t','t2','t3','watts_first','age','skin_temp_first','skin_temp_ema15','skin_temp_change'],
'both':['t','t2','t3','watts_first','age','hr_first','hr_change','hr_ema15','skin_temp_first','skin_temp_ema15','skin_temp_change'],
'all':list(rows[0]),
}
records=[]
for label,names in sets.items():
 X=np.array([[r[k] for k in names] for r in rows]);
 models=[]
 for C in [.2,1,5]:
  models.append(('svr'+str(C),make_pipeline(StandardScaler(),SVR(C=C,epsilon=.08,gamma=.05))))
 for leaf in [15,50]:models.append(('ET'+str(leaf),ExtraTreesRegressor(n_estimators=100,min_samples_leaf=leaf,max_features=.9,n_jobs=1,random_state=12)))
 if label!='all':models.append(('GB',GradientBoostingRegressor(n_estimators=100,learning_rate=.04,max_depth=2,min_samples_leaf=30,loss='absolute_error',random_state=2)))
 for modelname,model in models:
  p=np.zeros(len(y))
  for tr,te in folds:
   model.fit(X[tr],y[tr]);p[te]=model.predict(X[te])
  mae=np.mean([np.mean(np.abs(p[g==k]-y[g==k])) for k in ug]);records.append((mae,label,modelname,names,p,model))
  print(label,modelname,round(mae,4),flush=True)
# Interaction linear robust loss, including outlier-resistant median fitting.
ns=['t','t2','t3','watts_first','age','watts_first*t','watts_first*t2','age*t','age*t2']
for r in rows:
 for k in ns:
  if '*' in k:
   a,b=k.split('*');r[k]=r[a]*r[b]
X=np.array([[r[k] for k in ns] for r in rows]);
for alpha in [.1,1,10,100]:
 for eps in [1.1,1.35,2]:
  m=make_pipeline(StandardScaler(),HuberRegressor(alpha=alpha,epsilon=eps,max_iter=300));p=np.zeros(len(y))
  for tr,te in folds:
   m.fit(X[tr],y[tr]);p[te]=m.predict(X[te])
  mae=np.mean([np.mean(np.abs(p[g==k]-y[g==k])) for k in ug]);records.append((mae,'interact','huber'+str(alpha)+'_'+str(eps),ns,p,m));print('interact huber',alpha,eps,round(mae,4),flush=True)
pickle.dump(sorted(records,key=lambda x:x[0]),open('more_records.pkl','wb'))
PY
