{"argv":["bash","-lc","cat > hierarchical.py <<'PY'
import os
os.environ['OPENBLAS_NUM_THREADS']='1';os.environ['OMP_NUM_THREADS']='1'
import pickle,numpy as np
from sklearn.linear_model import Ridge,HuberRegressor
from sklearn.preprocessing import StandardScaler
rows,y,g=pickle.load(open('dataset.pkl','rb'));ug=np.unique(g)
for r in rows:
 for a in ['t','t2']:
  for b in ['watts_first','age','wkg_first','hr_first','skin_temp_first','mass','watts_drop','hr_change']:
   r[a+'*'+b]=r[a]*r[b]
 # Explicit workload reduction from starting workload.
 r['work_change']=r['work']-r['t']*(r['wkg_first']+2.4)*.4
 for tau in [5,15,30]:
  r['hr_dema'+str(tau)]=r['hr_ema'+str(tau)]-r['hr_first']
  r['skin_dema'+str(tau)]=r['skin_temp_ema'+str(tau)]-r['skin_temp_first']
sets={
 'time':['t','t2','t3'],
 'wage':['t','t2','t3','t*watts_first','t2*watts_first','t*age','t2*age'],
 'phys':['t','t2','t3','t*watts_first','t2*watts_first','t*age','t2*age','work','work_change','t*wkg_first','t2*wkg_first'],
 'hr':['t','t2','t3','t*watts_first','t2*watts_first','t*age','t2*age','hr_change','hr_dema5','hr_dema15','hr_dema30','t*hr_first','t2*hr_first'],
 'skin':['t','t2','t3','t*watts_first','t2*watts_first','t*age','t2*age','skin_temp_change','skin_dema5','skin_dema15','skin_dema30','t*skin_temp_first','t2*skin_temp_first'],
 'both':['t','t2','t3','t*watts_first','t2*watts_first','t*age','t2*age','hr_change','hr_dema15','t*hr_first','t2*hr_first','skin_temp_change','skin_dema15','t*skin_temp_first','t2*skin_temp_first'],
}
offsets=[['watts_first'],['watts_first','age'],['watts_first','age','mass'],['watts_first','age','skin_temp_first'],['watts_first','age','skin_temp_first','mass','height']]
class Model:
 def __init__(self,alpha=10,alpha2=1,shrink=0):self.alpha=alpha;self.alpha2=alpha2;self.shrink=shrink
 def fit(self,X,Z,y,g):
  un=np.unique(g);self.ss=StandardScaler().fit(X);x=self.ss.transform(X);xc=x.copy();yc=y.copy()
  for k in un:
   ix=g==k;xc[ix]-=x[ix].mean(0);yc[ix]-=y[ix].mean()
  self.m=Ridge(alpha=self.alpha,fit_intercept=False).fit(xc,yc)
  residual=y-self.m.predict(x)
  # One independent sample per person for predicting latent baseline.
  zz=np.array([Z[g==k].mean(0) for k in un]);a=np.array([residual[g==k].mean() for k in un]);self.sz=StandardScaler().fit(zz)
  self.m2=Ridge(alpha=self.alpha2).fit(self.sz.transform(zz),a)
  return self
 def predict(self,X,Z):return self.m.predict(self.ss.transform(X))+self.m2.predict(self.sz.transform(Z))
records=[]
for name,names in sets.items():
 X=np.array([[r[k] for k in names] for r in rows]);
 for zn in offsets:
  Z=np.array([[r[k] for k in zn] for r in rows])
  for a in [1,30,300]:
   for a2 in [.3,3,10]:
    p=np.zeros(len(y));m=Model(a,a2)
    for k in ug:
     tr=g!=k;te=g==k;m.fit(X[tr],Z[tr],y[tr],g[tr]);p[te]=m.predict(X[te],Z[te])
    mae=np.mean([np.mean(np.abs(p[g==k]-y[g==k])) for k in ug]);records.append((mae,name,names,zn,a,a2,p))
 print(name,'best',[(round(r[0],4),r[3:6]) for r in sorted([r for r in records if r[1]==name],key=lambda z:z[0])[:4]],flush=True)
pickle.dump(sorted(records,key=lambda x:x[0]),open('hierarchical_records.pkl','wb'))
PY
OPENBLAS_NUM_THREADS=1 OMP_NUM_THREADS=1 python3 -u hierarchical.py"],"timeout":60}

